queries.text:
// ------------------------------------------------------------
// Kachel 2: EE-Anteil an der Last jetzt     Visual: Stat (Einheit %)
// ------------------------------------------------------------
energy_latest
| where endpoint == "signal" and series_id == "share" and ts <= now()
| top 1 by ts desc
| project ["EE-Anteil %"] = round(value, 1)

// ------------------------------------------------------------
// Kachel 3: Netto-Import/Export jetzt       Visual: Stat (GW)
// positiv = Import, negativ = Export
// -

let cbpf_ts = energy_latest
    | where endpoint == "cbpf" and series_id != "sum"
    | summarize Gemeldet = countif(value != 0) by ts;
let cbpf_max = toscalar(energy_latest | where endpoint == "cbpf" | summarize max(ts));
let voll11 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 11 | summarize max(ts));
let voll10 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 10 | summarize max(ts));
let LetzterVollstaendig = iff(isnotnull(voll11) and voll11 >= cbpf_max - 6h, voll11, voll10);
energy_latest
| where endpoint == "cbpf" and series_id == "sum" and ts == LetzterVollstaendig
| project ["Netto-Import GW"] = round(value, 2),
          Stand = datetime_utc_to_local(ts, "Europe/Berlin")

// ------------------------------------------------------------
// Kachel 5: Last und Residuallast           Visual: Line chart
// Residuallast = Last minus Wind und Solar
// ------------------------------------------------------------
energy_latest
| where endpoint == "public_power"
    and series_id in ("load", "residual_load")
    and ts between (_startTime .. _endTime)
| project Zeit = datetime_utc_to_local(ts, "Europe/Berlin"),
          Reihe = iff(series_id == "load", "Last", "Residuallast"),
          GW = round(value / 1000, 2)
| order by Zeit asc

// ------------------------------------------------------------
// Kachel 7: Grenzflüsse je Nachbarland jetzt   Visual: Bar chart
// positiv = Import nach DE, negativ = Export
// ------------------------------------------------------------
let Laender = datatable(series_id: string, Land: string)
[
    "austria", "Österreich", "belgium", "Belgien", "czech_republic", "Tschechien",
    "denmark", "Dänemark", "france", "Frankreich", "luxembourg", "Luxemburg",
    "netherlands", "Niederlande", "norway", "Norwegen", "poland", "Polen",
    "sweden", "Schweden", "switzerland", "Schweiz"
];
let cbpf_ts = energy_latest
    | where endpoint == "cbpf" and series_id != "sum"
    | summarize Gemeldet = countif(value != 0) by ts;
let cbpf_max = toscalar(energy_latest | where endpoint == "cbpf" | summarize max(ts));
let voll11 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 11 | summarize max(ts));
let voll10 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 10 | summarize max(ts));
let LetzterVollstaendig = iff(isnotnull(voll11) and voll11 >= cbpf_max - 6h, voll11, voll10);
energy_latest
| where endpoint == "cbpf" and ts == LetzterVollstaendig
| join kind=inner Laender on series_id
| project Land, GW = round(value, 2)
| order by GW desc

// ------------------------------------------------------------
// Kachel 8: Netto-Import im Zeitverlauf     Visual: Line oder Column chart
// ------------------------------------------------------------
let cbpf_ts = energy_latest
    | where endpoint == "cbpf" and series_id != "sum"
    | summarize Gemeldet = countif(value != 0) by ts;
let cbpf_max = toscalar(energy_latest | where endpoint == "cbpf" | summarize max(ts));
let voll11 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 11 | summarize max(ts));
let voll10 = toscalar(cbpf_ts | where ts <= cbpf_max - 30m and Gemeldet >= 10 | summarize max(ts));
let LetzterVollstaendig = iff(isnotnull(voll11) and voll11 >= cbpf_max - 6h, voll11, voll10);
energy_latest
| where endpoint == "cbpf" and series_id == "sum"
    and ts between (_startTime .. _endTime) and ts <= LetzterVollstaendig
| project Zeit = datetime_utc_to_local(ts, "Europe/Berlin"), ["Netto-Import GW"] = round(value, 2)
| order by Zeit asc

// ------------------------------------------------------------
// Kachel 9: Datenstand je Quelle            Visual: Table
// Zeigt, wie aktuell die Daten sind (Energy-Charts veröffentlicht verzögert)
// ------------------------------------------------------------
energy_latest
| where ts <= now()
| summarize Letzter_Wert = max(ts), Letzter_Abruf = max(generated_at) by endpoint
| project Quelle = endpoint,
          ["Daten bis"] = datetime_utc_to_local(Letzter_Wert, "Europe/Berlin"),
          ["Verzögerung (min)"] = datetime_diff("minute", now(), Letzter_Wert),
          ["API-Stand"] = datetime_utc_to_local(Letzter_Abruf, "Europe/Berlin")

// ------------------------------------------------------------
// Kachel P1: Strompreis jetzt              Visual: Stat (ct/kWh)
// ------------------------------------------------------------
energy_latest
| where endpoint == "price" and ts <= now()
| top 1 by ts desc
| project ["Preis jetzt (ct/kWh)"] = round(value / 10, 2),
          Stand = datetime_utc_to_local(ts, "Europe/Berlin")

// ------------------------------------------------------------
// Kachel P2: Preiskurve heute + morgen     Visual: Column chart oder Line
//   Zeigt den ganzen heutigen Tag und – ab ca. 13 Uhr – auch morgen.
// ------------------------------------------------------------
let heute = startofday(datetime_utc_to_local(now(), "Europe/Berlin"));
energy_latest
| where endpoint == "price"
| extend Zeit = datetime_utc_to_local(ts, "Europe/Berlin")
| where Zeit >= heute and Zeit < heute + 2d
| project Zeit,
          Tag = iff(Zeit < heute + 1d, "Heute", "Morgen"),
          ["ct/kWh"] = round(value / 10, 2)
| order by Zeit asc

// ------------------------------------------------------------
// Kachel P4: Preis vs. Ökostrom-Anteil     Visual: Line chart (2 Achsen)
//   Zeigt schön: viel Ökostrom = niedriger Preis
// ------------------------------------------------------------
let preis = energy_latest
    | where endpoint == "price" and ts between (_startTime .. _endTime)
    | project ts, Preis_ct_kWh = round(value / 10, 2);
let ee = energy_latest
    | where endpoint == "public_power" and series_id == "renewable_share_of_load"
        and ts between (_startTime .. _endTime)
    | project ts, EE_Anteil_Prozent = round(value, 1);
preis
| join kind=fullouter ee on ts
| project Zeit = datetime_utc_to_local(coalesce(ts, ts1), "Europe/Berlin"),
          Preis_ct_kWh, EE_Anteil_Prozent
| order by Zeit asc
